import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Audit and Signature","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/forge/audit.md","filePath":"en/modules/forge/audit.md","lastUpdated":0}`),a={name:`en/modules/forge/audit.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="audit-and-signature" tabindex="-1">Audit and Signature <a class="header-anchor" href="#audit-and-signature" aria-label="Permalink to “Audit and Signature”">​</a></h1><p>EmakiForge writes audit data to forged result items after successful forging. This data helps trace the source recipe and validate whether material contribution data was tampered with.</p><h2 id="audit-data" tabindex="-1">Audit data <a class="header-anchor" href="#audit-data" aria-label="Permalink to “Audit data”">​</a></h2><p><code>ForgeAuditBuilder</code> writes data such as:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe_id</code></td><td>Recipe id used for forging.</td></tr><tr><td><code>quality</code></td><td>Quality tier name.</td></tr><tr><td><code>multiplier</code></td><td>Quality multiplier.</td></tr><tr><td><code>forged_at</code></td><td>Forge timestamp.</td></tr><tr><td><code>materials_signature</code></td><td>Stable hash signature of material contribution data.</td></tr><tr><td><code>output_item</code></td><td>Output item source shorthand. Written only when the recipe configures an output item source.</td></tr><tr><td><code>materials</code></td><td>Material contribution list.</td></tr></tbody></table><h2 id="material-signature" tabindex="-1">Material signature <a class="header-anchor" href="#material-signature" aria-label="Permalink to “Material signature”">​</a></h2><p><code>materials_signature</code> is computed only from material contributions whose consumed amount is greater than zero. The same set of material contributions always yields the same signature, so it can be used to compare an item&#39;s forging material data against an expected value.</p><h2 id="relationship-with-refresh" tabindex="-1">Relationship with refresh <a class="header-anchor" href="#relationship-with-refresh" aria-label="Permalink to “Relationship with refresh”">​</a></h2><p>The Forge item refresh service reads <code>recipe_id</code> and <code>quality</code> from the audit data to rebuild the forge layer presentation. Items whose audit data is missing, or whose recipe has been deleted, cannot have their forge layer rebuilt.</p><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use cases”">​</a></h2><ul><li>Trading or recycling systems can read audit data to determine an item&#39;s source recipe and quality.</li><li>External analytics can aggregate forge output by <code>recipe_id</code>, <code>quality</code>, and <code>forged_at</code>.</li></ul><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Forge does not ship a built-in command for viewing audit data. Use an external tool that can read item PDC when manual inspection is needed.</p></div>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};